create or replace function record_stripe_rental_settlement(p_provider_event_id text,p_connected_account_id text,p_payment_intent_id text,p_balance_transaction_id text,p_gross_amount_cents bigint,p_fee_amount_cents bigint,p_net_amount_cents bigint,p_currency_code text,p_status text,p_available_at timestamptz)returns jsonb language plpgsql security invoker set search_path=public as $$declare v_owner text;v_payment rental_payments;begin
select owner_id into v_owner from landlord_payment_accounts where provider='stripe' and provider_account_id=p_connected_account_id;select * into v_payment from rental_payments where owner_id=v_owner and provider='stripe' and provider_payment_id=p_payment_intent_id;if v_payment.id is null then raise exception 'Settlement payment mapping was not found.';end if;if p_gross_amount_cents-p_fee_amount_cents<>p_net_amount_cents then raise exception 'Settlement arithmetic is invalid.';end if;
insert into rental_settlements(owner_id,id,payment_id,provider,provider_balance_transaction_id,gross_amount_cents,fee_amount_cents,net_amount_cents,currency_code,status,available_at)values(v_owner,'rental_settlement_'||gen_random_uuid()::text,v_payment.id,'stripe',p_balance_transaction_id,p_gross_amount_cents,p_fee_amount_cents,p_net_amount_cents,upper(p_currency_code),case when p_status='available' then 'available' else 'pending' end,p_available_at)on conflict(provider,provider_balance_transaction_id)do update set fee_amount_cents=excluded.fee_amount_cents,net_amount_cents=excluded.net_amount_cents,status=excluded.status,available_at=excluded.available_at,updated_at=now();update payment_webhook_events set status='processed',processed_at=now()where provider='stripe'and provider_event_id=p_provider_event_id;return jsonb_build_object('status','processed','payment_id',v_payment.id);end$$;
create or replace function mark_stripe_rental_settlements_paid_out(p_provider_event_id text,p_connected_account_id text,p_payout_id text,p_balance_transaction_ids text[],p_paid_out_at timestamptz)returns jsonb language plpgsql security invoker set search_path=public as $$declare v_owner text;v_count integer;begin select owner_id into v_owner from landlord_payment_accounts where provider='stripe'and provider_account_id=p_connected_account_id;update rental_settlements set provider_payout_id=p_payout_id,status='paid_out',paid_out_at=p_paid_out_at,updated_at=now()where owner_id=v_owner and provider='stripe'and provider_balance_transaction_id=any(p_balance_transaction_ids);get diagnostics v_count=row_count;update payment_webhook_events set status='processed',processed_at=now()where provider='stripe'and provider_event_id=p_provider_event_id;return jsonb_build_object('status','processed','matched_settlements',v_count);end$$;
revoke all on function record_stripe_rental_settlement(text,text,text,text,bigint,bigint,bigint,text,text,timestamptz)from public,anon,authenticated;grant execute on function record_stripe_rental_settlement(text,text,text,text,bigint,bigint,bigint,text,text,timestamptz)to service_role;
revoke all on function mark_stripe_rental_settlements_paid_out(text,text,text,text[],timestamptz)from public,anon,authenticated;grant execute on function mark_stripe_rental_settlements_paid_out(text,text,text,text[],timestamptz)to service_role;
